import data from "./easing.json";
import { smart } from "./typo.mjs";

// Generated by scripts/site/easing.mjs from core/motion. Server code only: the linear() strings make
// the file about 170 KB, so a client component gets one ease's arrays, never this module.

export type Related = { slug: string; name: string; gap: number };
export type Side = { influence: number; speed: number; name: string | null };
export type Ease = {
  slug: string;
  name: string;
  kind: "vawe" | "classic" | "css";
  family: string;
  dir: "in" | "out" | "inOut" | null;
  y: number[];
  vel: number[];
  t50: number;
  t90: number;
  at10: number;
  peakSpeed: number;
  overshoot: number;
  undershoot: number;
  linear: string;
  points: number;
  bezier: { params: number[]; exact?: boolean; worst?: number; usable?: boolean; express?: "exact" | "close" | "no" };
  blurb: string;
  use: string[];
  avoid: string[];
  related: Related[];
  nearestVawe?: Related | null;
  handles?: {
    out: Side;
    in: Side;
    shares: { outShare: number; inShare: number; pairShare: number; pairCount: number; entranceShare: number; exitShare: number; hfCount: number };
  };
  moves?: { name: string; title: string; uses: number }[];
  jobs?: { id: string; job: string; time: string }[];
};

export type Job = { id: string; job: string; ease: string; easeName: string; also: { slug: string; name: string }[]; time: string; avoid: string };
export type ProductUi = {
  window: number;
  realFirstFrame: number[];
  rows: { name: string; value: string; rule: string }[];
  approach: { k: number; tau: number; settle99: number; nearest: Related }[];
  firstFrame: { at: number[]; rows: { slug: string; name: string; shares: number[] }[] };
  realSurface: string[];
};

const typeset = (e: Ease): Ease => ({ ...e, blurb: smart(e.blurb), use: e.use.map(smart), avoid: e.avoid.map(smart), jobs: e.jobs?.map((j) => ({ ...j, time: smart(j.time) })) });

export const EASES = (data.eases as Ease[]).map(typeset);
export const STATS = data.stats;
export const JOBS = (data.jobs as Job[]).map((j) => ({ ...j, time: smart(j.time), avoid: smart(j.avoid[0].toUpperCase() + j.avoid.slice(1)) }));
const ui = data.ui as ProductUi;
export const PRODUCT_UI: ProductUi = { ...ui, rows: ui.rows.map((r) => ({ name: r.name, value: smart(r.value), rule: smart(r.rule) })), realSurface: ui.realSurface.map(smart) };
export const FAMILIES = data.families as string[];

export const easeBySlug = (slug: string) => EASES.find((e) => e.slug === slug) ?? null;
export const VAWE = EASES.filter((e) => e.kind === "vawe");
export const CSS = EASES.filter((e) => e.kind === "css");
export const classicIn = (family: string) => EASES.filter((e) => e.kind === "classic" && e.family === family);

export const PUBLISHED = "2026-10-03";

const pct = (u: number) => `${Math.round(u * 100)}%`;
const bez = (p: number[]) => `cubic-bezier(${p.join(", ")})`;
export const bezierText = (e: Ease) => bez(e.bezier.params);
export const camelOf = (slug: string) => slug.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
export const speedText = (e: Ease) => (e.peakSpeed > 20 ? "over 20x (it ends vertically)" : `${e.peakSpeed}x`);

export function pageTitle(e: Ease) {
  if (e.kind === "vawe") return `After Effects easing in CSS: ${e.slug} (speed and influence) | vawe`;
  if (e.kind === "css") return `CSS ${e.name}: cubic-bezier and linear() easing | vawe`;
  if (e.bezier.express === "no") return `${e.name}: CSS linear() easing (no cubic-bezier fit) | vawe`;
  return `${e.name}: CSS cubic-bezier and linear() easing | vawe`;
}

export function summary(e: Ease) {
  const shape = e.overshoot > 0 ? ` It passes the end value by up to ${e.overshoot}%.` : e.undershoot > 0 ? ` It dips ${e.undershoot}% below the start value first.` : "";
  return `${e.name} reaches 50% of its travel at ${pct(e.t50)} of the time and 90% at ${pct(e.t90)}. Its peak speed is ${speedText(e)} the average.${shape}`;
}

export function pageDescription(e: Ease) {
  const lead =
    e.kind === "vawe"
      ? `${e.slug}: the After Effects handles (influence and speed), the CSS linear() string, and a live demo.`
      : e.bezier.express === "no"
        ? `${e.name} as CSS: the exact linear() string, why cubic-bezier cannot draw it, and a live demo.`
        : `${e.name} as CSS: the cubic-bezier, the exact linear() string, and a live demo.`;
  const text = `${lead} 50% at ${pct(e.t50)} of the time.`;
  return text.length <= 154 ? text : lead;
}

export function waapi(e: Ease) {
  const easing = e.bezier.express === "exact" || e.kind === "css" ? bezierText(e) : e.linear;
  return `el.animate({ translate: ['0 0', '240px 0'] }, { duration: 600, easing: '${easing}', fill: 'both' });`;
}

const EXIT_EASES = ["launch", "leave"];
const EXIT_EXAMPLE = data.exitExample as { entranceS: number; exitMs: number };
const EXIT_SHARE = EXIT_EXAMPLE.exitMs / (EXIT_EXAMPLE.entranceS * 1000);

export function importLine(e: Ease) {
  if (e.kind === "vawe" && EXIT_EASES.includes(e.slug)) return `import { EASE } from '../../core/motion/presets.js';\n\n// ${EXIT_EXAMPLE.exitMs / 1000} s: ${EXIT_SHARE} of a ${EXIT_EXAMPLE.entranceS} s entrance. fill forwards, never both: a backwards fill would cover the entrance.\nel.animate(\n  [{ translate: '0 0', opacity: 1 }, { translate: '0 -0.3em', opacity: 0 }],\n  { duration: ${EXIT_EXAMPLE.exitMs}, easing: EASE.${camelOf(e.slug)}, fill: 'forwards' },\n);\n\n// the helper does the same from the entrance's length: leave(el, { ease: '${camelOf(e.slug)}' })\n// per-frame code (window.seek, vawe.onFrame): easeFn('${camelOf(e.slug)}')(u)`;
  if (e.kind === "vawe") return `import { EASE } from '../../core/motion/presets.js';\n\nel.animate(\n  [{ translate: '0 4vh', opacity: 0 }, { translate: '0 0', opacity: 1 }],\n  { duration: 500, easing: EASE.${camelOf(e.slug)}, fill: 'both' },\n);\n\n// per-frame code (window.seek, vawe.onFrame): easeFn('${camelOf(e.slug)}')(u)`;
  if (e.kind === "css") return `animation: slide 600ms ${e.name};`;
  return `import { ${e.name} } from '../../core/motion/curves.js';\nimport { curveToLinear } from '../../core/motion/springs.js';\n\nconst easing = curveToLinear(${e.name}, { tolerance: 0.002 }); // the linear() string above\nconst x = ${e.name}(u);                                         // per-frame code, u in 0..1`;
}

export const ROLES = ["Entrance", "Exit", "Move", "Overshoot"] as const;
export type Role = (typeof ROLES)[number];

const VAWE_ROLE: Record<string, Role> = { land: "Entrance", "land-soft": "Entrance", leave: "Exit", launch: "Exit", settle: "Move", swap: "Move", glide: "Move", carry: "Move", pop: "Overshoot", nudge: "Overshoot" };
const CSS_ROLE: Record<string, Role> = { linear: "Move", ease: "Move", "ease-in": "Exit", "ease-out": "Entrance", "ease-in-out": "Move" };
const DIR_ROLE = { in: "Exit", out: "Entrance", inOut: "Move" } as const;

export function roleOf(e: Ease): Role {
  if (e.kind === "vawe") return VAWE_ROLE[e.slug];
  if (e.kind === "css") return CSS_ROLE[e.slug];
  if (e.family === "back" || e.family === "elastic" || e.family === "bounce") return "Overshoot";
  return DIR_ROLE[e.dir ?? "inOut"];
}

export const jobIdsOf = (slug: string) => JOBS.filter((j) => j.ease === slug || j.also.some((a) => a.slug === slug)).map((j) => j.id);

export const copyIsBezier = (e: Ease) => e.kind !== "classic" || e.bezier.express !== "no";
export const copyValue = (e: Ease) => (copyIsBezier(e) ? bezierText(e) : e.linear);

const ORG = { "@type": "Organization", name: "vawe", url: "https://vawe.dev" };

export function techArticleSchema(e: Ease) {
  return {
    "@context": "https://schema.org",
    "@type": "TechArticle",
    headline: pageTitle(e).replace(/ \| vawe$/, ""),
    description: pageDescription(e),
    url: `https://vawe.dev/easing/${e.slug}`,
    inLanguage: "en",
    proficiencyLevel: "Beginner",
    datePublished: PUBLISHED,
    dateModified: PUBLISHED,
    author: ORG,
    publisher: ORG,
    about: e.kind === "vawe" ? "After Effects keyframe handles as CSS easing" : "CSS easing function",
  };
}

export function itemListSchema() {
  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: "Easing functions for CSS, Web Animations and After Effects",
    numberOfItems: EASES.length,
    itemListElement: EASES.map((e, i) => ({ "@type": "ListItem", position: i + 1, name: e.name, url: `https://vawe.dev/easing/${e.slug}` })),
  };
}
